inline constexpr uint32_t cursorPalettePixel(int style,uint32_t c){
    if(!(c>>24))return 0;
    const unsigned r=(c>>16)&255,g=(c>>8)&255,b=c&255;
    const unsigned l=(r*30+g*59+b*11)/100;
    if(style==2)return l<64?0xff580e12u:l<200?0xffda241cu:0xffec9236u;
    if(style==3)return l<64?0xff4b2d12u:l<200?0xffb6732cu:0xffe3be89u;
    if(style==4)return l<64?0xff132718u:l<200?0xff4c8045u:0xffa5c16bu;
    return l<64?0xff3a3a3au:l<200?0xff919191u:0xffe0e0e0u;
}
